<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { workApi } from '../workApi'
import { t } from '../i18n'
const caps=ref<any[]>([]),providers=ref<any[]>([]),mcp=ref<any[]>([]),terms=ref<any[]>([]),doctor=ref<any>(null),policy=ref({text:'',blockedCommands:[] as string[]}),blocked=ref('')
const cap=ref<any>({id:'',name:'',transport:'cli',enabled:true,command:'',args:[],providerId:'',prompt:'',roles:['worker'],envAllowlist:[]}),capArgs=ref('[]')
const provider=ref<any>({id:'',name:'',protocol:'openai',baseUrl:'',model:'',apiKey:'',proxyUrl:'',rates:null})
const rates=ref('null'),server=ref({name:'',transport:'http',endpoint:'',enabled:true}),term=ref({term:'',context:'Workflow',definition:'',aliases:''})
const workspacePath=ref(''),workspaces=ref<any[]>([]),busy=ref(false)
async function safe(fn:()=>Promise<any>) { busy.value=true;try{await fn()}catch(e:any){ElMessage.error(e.response?.data?.message||e.message)}finally{busy.value=false} }
async function load(){const results=await Promise.all(['/capabilities','/providers','/mcp','/governance','/workspaces'].map(p=>workApi.get(p)));caps.value=results[0].data;providers.value=results[1].data;mcp.value=results[2].data;terms.value=results[3].data.terms;policy.value=results[3].data.policy;blocked.value=policy.value.blockedCommands.join('\n');workspaces.value=results[4].data}
function editCap(c:any){cap.value=JSON.parse(JSON.stringify(c));capArgs.value=JSON.stringify(c.args)}
async function saveCap(){await workApi.post('/capabilities',{...cap.value,args:JSON.parse(capArgs.value)});await load()}
async function saveProvider(){await workApi.post('/providers',{...provider.value,rates:JSON.parse(rates.value)});provider.value.apiKey='';await load()}
onMounted(()=>safe(load))
</script>
<template><div class="wb-infra" v-loading="busy">
 <div class="wb-section-heading"><div><h2>{{t('能力与运行环境','Capabilities & environment')}}</h2><p>{{t('配置执行能力，查看真实探测状态。','Configure executors and inspect measured health.')}}</p></div><el-button @click="safe(async()=>{doctor=(await workApi.post('/doctor')).data;await load()})">{{t('检查环境','Run doctor')}}</el-button></div>
 <el-alert v-if="doctor" :title="`${doctor.gitReady?'Git ✓':'Git ×'} · ${doctor.gitVersion}`" :closable="false" type="info"/>
 <div class="wb-card-grid">
 <section class="wb-card"><h3>{{t('执行能力池','Capability pool')}}</h3><div v-for="c in caps" :key="c.id" class="wb-entry"><div><b>{{c.name}}</b><small>{{c.transport}} · {{c.enabled?c.circuit:'disabled'}}</small></div><div><el-button size="small" @click="editCap(c)">{{t('编辑','Edit')}}</el-button><el-button size="small" @click="safe(async()=>{const r=await workApi.post(`/capabilities/${c.id}/probe`);ElMessage.info(r.data.message);await load()})">{{t('探测','Probe')}}</el-button><el-button size="small" @click="safe(async()=>{await workApi.post('/capabilities',{...c,enabled:!c.enabled});await load()})">{{c.enabled?t('停用','Disable'):t('启用','Enable')}}</el-button></div></div>
 <details><summary>{{t('登记 / 修改能力','Register / edit capability')}}</summary><label>ID<input v-model="cap.id" aria-label="Capability ID"/></label><label>{{t('名称','Name')}}<input v-model="cap.name" aria-label="Capability name"/></label><label>{{t('适配协议','Transport')}}<select v-model="cap.transport"><option v-for="v in ['simulated','local','native','cli','acp']">{{v}}</option></select></label><label>{{t('命令','Executable')}}<input v-model="cap.command"/></label><label>{{t('参数 JSON','Arguments JSON')}}<input v-model="capArgs"/></label><label>{{t('供应商 ID','Provider ID')}}<select v-model="cap.providerId"><option value="">—</option><option v-for="p in providers" :value="p.id">{{p.id}}</option></select></label><label>{{t('能力提示词','Capability prompt')}}<textarea v-model="cap.prompt"/></label><el-button type="primary" @click="safe(saveCap)">{{t('保存能力','Save capability')}}</el-button></details></section>
 <section class="wb-card"><h3>{{t('模型供应商','Model providers')}}</h3><div v-for="p in providers" :key="p.id" class="wb-entry"><div><b>{{p.name}}</b><small>{{p.model}} · {{p.hasApiKey?'••••••••':t('未配置密钥','No key')}}</small></div><el-button size="small" @click="provider={...p,apiKey:undefined};rates=JSON.stringify(p.rates)">{{t('编辑','Edit')}}</el-button></div>
 <details><summary>{{t('配置供应商','Configure provider')}}</summary><label>ID<input v-model="provider.id"/></label><label>{{t('名称','Name')}}<input v-model="provider.name"/></label><label>{{t('协议','Protocol')}}<select v-model="provider.protocol"><option value="openai">OpenAI compatible</option><option value="anthropic">Anthropic</option></select></label><label>Base URL<input v-model="provider.baseUrl"/></label><label>{{t('模型','Model')}}<input v-model="provider.model"/></label><label>API Key<input v-model="provider.apiKey" type="password" autocomplete="new-password"/></label><label>{{t('代理 URL（可选）','Proxy URL (optional)')}}<input v-model="provider.proxyUrl"/></label><label>{{t('每百万 Token 费率 JSON：input/cached/output','USD per million JSON: input/cached/output')}}<input v-model="rates"/></label><el-button type="primary" @click="safe(saveProvider)">{{t('保存供应商','Save provider')}}</el-button><p class="wb-muted">{{t('留空保存可清除密钥。探测配置完整不代表供应商访问成功。','Saving an empty key clears it. Configuration checks do not verify live access.')}}</p></details></section>
 <section class="wb-card"><h3>{{t('MCP 服务登记','MCP service registry')}}</h3><p class="wb-muted">{{t('仅检查连通性或程序存在，不宣称工具握手。','Connectivity or executable presence only; no tool handshake claim.')}}</p><div v-for="m in mcp" :key="m.id" class="wb-entry"><div><b>{{m.name}}</b><small>{{m.status}} · {{m.detail||m.transport}}</small></div><el-button size="small" @click="safe(async()=>{await workApi.post(`/mcp/${m.id}/probe`);await load()})">{{t('探测','Probe')}}</el-button><el-button size="small" @click="safe(async()=>{await workApi.post('/mcp',{...m,enabled:!m.enabled});await load()})">{{m.enabled?t('停用','Disable'):t('启用','Enable')}}</el-button></div><label>{{t('名称','Name')}}<input v-model="server.name" aria-label="MCP name"/></label><label>{{t('传输方式','Transport')}}<select v-model="server.transport"><option>http</option><option>stdio</option></select></label><label>{{t('端点 / 可执行文件','Endpoint / executable')}}<input v-model="server.endpoint" aria-label="MCP endpoint"/></label><el-button @click="safe(async()=>{await workApi.post('/mcp',server);await load()})">{{t('登记 MCP','Register MCP')}}</el-button></section>
 <section class="wb-card"><h3>{{t('领域术语','Domain terminology')}}</h3><div v-for="d in terms" :key="d.id" class="wb-entry"><div><b>{{d.term}}</b><small>{{d.context}} · {{d.aliases.join(', ')}}</small></div><el-button size="small" @click="safe(async()=>{await workApi.delete(`/governance/terms/${d.id}`);await load()})">{{t('删除','Remove')}}</el-button></div><label>{{t('规范术语','Canonical term')}}<input v-model="term.term" aria-label="Canonical term"/></label><label>{{t('上下文','Context')}}<input v-model="term.context"/></label><label>{{t('不推荐别名，逗号分隔','Discouraged aliases, comma separated')}}<input v-model="term.aliases" aria-label="Term aliases"/></label><label>{{t('定义','Definition')}}<textarea v-model="term.definition"/></label><el-button @click="safe(async()=>{await workApi.post('/governance/terms',{...term,aliases:term.aliases.split(/[,，]/).map(x=>x.trim()).filter(Boolean)});await load()})">{{t('保存术语','Save term')}}</el-button></section>
 <section class="wb-card"><h3>{{t('工程规则','Engineering rules')}}</h3><label>{{t('规则说明','Policy text')}}<textarea v-model="policy.text" rows="4"/></label><label>{{t('禁止命令片段，每行一项','Blocked command fragments, one per line')}}<textarea v-model="blocked" rows="4" aria-label="Blocked commands"/></label><el-button @click="safe(async()=>{await workApi.post('/governance/policy',{text:policy.text,blockedCommands:blocked.split('\n').filter(Boolean)});await load()})">{{t('保存规则','Save rules')}}</el-button></section>
 <section class="wb-card"><h3>{{t('Git 工作区','Git workspaces')}}</h3><div v-for="w in workspaces" :key="w.id" class="wb-entry"><div><b>{{w.name}}</b><small>{{w.rootPath}}</small></div></div><label>{{t('已有仓库绝对路径','Absolute path to existing repository')}}<input v-model="workspacePath" aria-label="Workspace path"/></label><el-button @click="safe(async()=>{await workApi.post('/workspaces',{rootPath:workspacePath});await load()})">{{t('登记工作区','Register workspace')}}</el-button><el-button @click="safe(async()=>{await workApi.post('/workspaces/demo');await load()})">{{t('创建演示仓库','Create demo repository')}}</el-button></section>
 </div></div></template>
